translate the question "List all song names by singers above the average age." into SPARQL.

execution_result.cleaned_query:
SELECT ?song_name
WHERE {
  ?singer a :singer .
  ?singer :singer\#age ?age .
  ?singer :singer\#song_name ?song_name .

  FILTER(?age > ?average_age)

  {
    SELECT (AVG(?age) AS ?average_age)
    WHERE {
      ?singer a :singer .
      ?singer :singer\#age ?age .
    }
  }
}

