translate the question "What are all the song names by singers who are older than average?" into SPARQL.

execution_result.cleaned_query:
SELECT ?song_name
WHERE {
  # Calculate the average age of all singers
  {
    SELECT (AVG(?age) AS ?average_age)
    WHERE {
      ?singer a :singer .
      ?singer :singer\#age ?age .
    }
  }

  # Find singers older than the average age
  ?singer a :singer .
  ?singer :singer\#age ?age .
  ?singer :singer\#song_name ?song_name .
  FILTER(?age > ?average_age)
}

