translate the question "Find the number of concerts happened in the stadium with the highest capacity ." into SPARQL.

execution_result.cleaned_query:
select (count(distinct ?concert) as ?num_concerts) where {
  ?stadium a :stadium .
  ?stadium :stadium\#capacity ?capacity .
  ?concert a :concert .
  ?concert :concert\#ref-stadium_id ?stadium .
  filter(?capacity = ?max_capacity)
  {
    select (max(?capacity) as ?max_capacity) where {
      ?stadium a :stadium .
      ?stadium :stadium\#capacity ?capacity .
    }
  }
}

