translate the question "What are the number of concerts that occurred in the stadium with the largest capacity ?" into SPARQL.

execution_result.cleaned_query:
SELECT (COUNT(?concert) AS ?numConcerts) WHERE {
  ?stadium a :stadium .
  ?stadium :stadium\#capacity ?capacity .
  ?concert a :concert .
  ?concert :concert\#ref-stadium_id ?stadium .
  FILTER(?capacity = ?maxCapacity)
  {
    SELECT (MAX(?capacity) AS ?maxCapacity) WHERE {
      ?stadium a :stadium .
      ?stadium :stadium\#capacity ?capacity .
    }
  }
}
